//! Rolling context management for the agent loop.
//!
//! The model conversation grows by one turn every step. `ContextManager`
//! estimates the token size of the conversation that will next be sent to the
//! model, reports when it crosses a warm-up threshold, and compacts the oldest
//! completed turns into a concise rolling summary while the most recent turns
//! stay in full.
//!
//! Compaction only ever removes material from the *model* context. The full
//! transcript, including every reasoning trace, is preserved separately in the
//! durable session log (`crate::session_log`); a compacted turn is never lost,
//! it is simply moved from the live context into the record. This keeps the
//! model's context bounded without weakening the audit trail Kvist relies on.

use agent_runtime::ModelMessage;

/// Approximate tokens per character (the widely used ~4 chars/token rule).
const CHARS_PER_TOKEN: usize = 4;
/// Per-message framing overhead in the request, in tokens.
const MESSAGE_OVERHEAD_TOKENS: usize = 4;
/// Per tool-definition framing overhead in the request, in tokens.
const TOOL_DEFINITION_OVERHEAD_TOKENS: usize = 8;
/// Maximum length of the rolling summary before it is trimmed.
const MAX_SUMMARY_CHARS: usize = 4_000;

/// Estimates the token size of a block of text using the ~4-chars-per-token
/// heuristic. Cheap and deterministic; the provider-reported usage is
/// authoritative for speed stats.
pub fn estimate_tokens(text: &str) -> usize {
    text.chars().count().div_ceil(CHARS_PER_TOKEN)
}

fn estimate_intent_tokens(intent: &agent_runtime::ToolIntent) -> usize {
    match serde_json::to_string(intent) {
        Ok(json) => estimate_tokens(&json) + MESSAGE_OVERHEAD_TOKENS,
        Err(_) => MESSAGE_OVERHEAD_TOKENS,
    }
}

fn message_tokens(message: &ModelMessage) -> usize {
    let mut total = MESSAGE_OVERHEAD_TOKENS;
    match message {
        ModelMessage::System(text) | ModelMessage::User(text) => total += estimate_tokens(text),
        ModelMessage::Assistant { text, tool_intents } => {
            total += estimate_tokens(text);
            for intent in tool_intents {
                total += estimate_intent_tokens(intent);
            }
        }
        ModelMessage::ToolResult { content, .. } => total += estimate_tokens(content),
    }
    total
}

/// Estimates the token size of the message list that would be sent as one
/// request, accounting for each message plus the always-present tool
/// definitions. This is the figure `ContextManager` tracks against its limits.
pub fn estimate_messages(messages: &[ModelMessage], tool_definitions: usize) -> usize {
    let mut total = tool_definitions * TOOL_DEFINITION_OVERHEAD_TOKENS;
    for message in messages {
        total += message_tokens(message);
    }
    total
}

fn utilization(used: usize, limit: usize) -> f64 {
    if limit == 0 {
        0.0
    } else {
        used as f64 / limit as f64
    }
}

/// Information about a compaction, returned to the caller (and the UI) so it
/// can be logged and shown as progress.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Compaction {
    /// How many completed turns were rolled into the summary.
    pub compacted_turns: usize,
    /// Length of the rolling summary after compaction, in characters.
    pub summary_chars: usize,
}

/// The default context window assumed when the model is unknown.
pub const DEFAULT_CONTEXT_TOKENS: usize = 8_192;

/// Rolling context manager: estimates context size and compacts the oldest
/// completed turns into a summary.
#[derive(Debug, Clone)]
pub struct ContextManager {
    /// Hard limit on the model context, in tokens.
    limit_tokens: usize,
    /// Start compacting above this many tokens (75% of the limit by default).
    warmup_tokens: usize,
    /// The most recent completed turns always stay in full, never summarized.
    keep_full_turns: usize,
    /// Rolling summary text representing compacted history.
    summary: String,
}

impl ContextManager {
    /// Builds a manager for a model context window of `limit_tokens`.
    ///
    /// Compaction begins at 75% of the window and always keeps the last
    /// `keep_full_turns` completed turns in full.
    pub fn new(limit_tokens: usize, keep_full_turns: usize) -> Self {
        let warmup_tokens = limit_tokens.div_ceil(4) * 3;
        Self::with_bounds(limit_tokens, warmup_tokens, keep_full_turns)
    }

    /// Builds a manager with explicit warm-up and hard limits. Exposed for
    /// tests and for tuning on models with small windows.
    pub fn with_bounds(limit_tokens: usize, warmup_tokens: usize, keep_full_turns: usize) -> Self {
        debug_assert!(limit_tokens > warmup_tokens, "limit must exceed warm-up");
        debug_assert!(
            keep_full_turns >= 1,
            "at least one turn must be kept in full"
        );
        ContextManager {
            limit_tokens,
            warmup_tokens,
            keep_full_turns,
            summary: String::new(),
        }
    }

    /// The hard context limit, in tokens.
    pub fn limit_tokens(&self) -> usize {
        self.limit_tokens
    }

    /// The warm-up threshold at or above which compaction begins, in tokens.
    pub fn warmup(&self) -> usize {
        self.warmup_tokens
    }

    /// How many completed turns are always kept in full.
    pub fn keep_full_turns(&self) -> usize {
        self.keep_full_turns
    }

    /// The current rolling summary text.
    pub fn summary(&self) -> &str {
        &self.summary
    }

    /// Whether the estimated `context_tokens` has crossed the warm-up threshold
    /// and compaction should be performed before the next request.
    pub fn should_compact(&self, context_tokens: usize) -> bool {
        context_tokens > self.warmup_tokens
    }

    /// How far compaction is from the hard limit, as a fraction in
    /// `0.0..=1.0`. Zero at or below warm-up; one at or above the limit. This is
    /// the value a compaction progress bar renders.
    pub fn compaction_progress(&self, context_tokens: usize) -> f64 {
        if context_tokens <= self.warmup_tokens {
            0.0
        } else if context_tokens >= self.limit_tokens {
            1.0
        } else {
            (context_tokens - self.warmup_tokens) as f64
                / (self.limit_tokens - self.warmup_tokens) as f64
        }
    }

    /// Whether the estimated `context_tokens` has reached or passed the limit,
    /// meaning a request would be rejected by the model.
    pub fn at_limit(&self, context_tokens: usize) -> bool {
        context_tokens >= self.limit_tokens
    }

    /// The current context utilization fraction against the hard limit
    /// (`0.0..=1.0+`), for the context bargraph.
    pub fn utilization(&self, context_tokens: usize) -> f64 {
        utilization(context_tokens, self.limit_tokens)
    }

    /// Compacts `messages` (excluding the leading system message, which is
    /// preserved) by rolling the oldest completed turns into the summary and
    /// keeping the most recent turns in full. Returns the condensed message
    /// list and compaction metadata. No-ops when there is nothing past
    /// `keep_full_turns` to roll.
    ///
    /// Compaction keeps as many of the most recent turns in full as fit under
    /// the hard `limit_tokens`, rolling the rest into the summary. It starts by
    /// keeping `keep_full_turns` recent turns in full, then keeps rolling more
    /// into the summary (reducing how many recent turns stay full) until the
    /// estimated context is bounded. This guarantees a long-running session's
    /// live context stays under the window even when individual turns are large;
    /// the single most recent turn is always kept in full as a best effort,
    /// since that is the only case where keeping it cannot bring the context
    /// under the limit.
    pub fn compact(
        &mut self,
        messages: &[ModelMessage],
        tool_definitions: usize,
    ) -> (Vec<ModelMessage>, Compaction) {
        let mut turns: Vec<&ModelMessage> = Vec::new();
        let mut system: Option<&ModelMessage> = None;
        for message in messages {
            match message {
                ModelMessage::System(_) => system = Some(message),
                _ => turns.push(message),
            }
        }

        let segments = segment_turns(&turns);
        if segments.len() <= self.keep_full_turns {
            let condensed = keep_segments(messages, &segments, self.keep_full_turns);
            return (
                condensed,
                Compaction {
                    compacted_turns: 0,
                    summary_chars: self.summary.chars().count(),
                },
            );
        }

        // The single most recent turn must always stay in full so the model
        // keeps its immediate context and any pending tool continuity; everything
        // older rolls into the summary. Keep as many recent turns in full as fit
        // under the hard limit, compacting more as needed.
        const MIN_KEEP_FULL_TURNS: usize = 1;
        let total = segments.len();
        let mut keep = self
            .keep_full_turns
            .min(total.saturating_sub(MIN_KEEP_FULL_TURNS));
        keep = keep.max(MIN_KEEP_FULL_TURNS);

        // Accumulated summary lines, oldest first; appended to as `keep` shrinks,
        // so each pass folds one more older segment into the rolling summary.
        // Each segment is summarized exactly once: `summarized` tracks how many
        // leading segments already have a line, so a second pass only adds the
        // newly compacted segment instead of re-duplicating the earlier ones.
        let mut summary_parts: Vec<String> = Vec::new();
        let mut summarized = 0usize;
        loop {
            let (compactable, kept) = segments.split_at(total - keep);
            for segment in &compactable[summarized..] {
                let line = turn_summary(segment);
                if !line.is_empty() {
                    summary_parts.push(line);
                }
            }
            summarized = compactable.len();
            let rolled = bounded_summary(&summary_parts);

            let mut condensed = Vec::new();
            if let Some(sys) = system {
                condensed.push(sys.clone());
            }
            if !rolled.is_empty() {
                condensed.push(ModelMessage::User(format!(
                    "## Summary of prior work ({} earlier turn(s), kept in the session log):\n{}",
                    compactable.len(),
                    rolled
                )));
            }
            for segment in kept {
                for &message in segment {
                    condensed.push(message.clone());
                }
            }

            let summary_chars = rolled.chars().count();
            if estimate_messages(&condensed, tool_definitions) < self.limit_tokens
                || keep <= MIN_KEEP_FULL_TURNS
            {
                self.summary = rolled;
                return (
                    condensed,
                    Compaction {
                        compacted_turns: total - keep,
                        summary_chars,
                    },
                );
            }
            keep -= 1;
        }
    }
}

/// Joins accumulated summary lines (oldest first) and trims the result to
/// `MAX_SUMMARY_CHARS`, keeping the most recent content so the rolling summary
/// never grows past its bound.
fn bounded_summary(parts: &[String]) -> String {
    let mut joined = parts.join("\n");
    if joined.chars().count() > MAX_SUMMARY_CHARS {
        let trim = joined.chars().count() - MAX_SUMMARY_CHARS;
        joined = joined.chars().skip(trim).collect();
        joined.push('\u{2026}');
    }
    joined
}

/// Splits an ordered conversation into segments, each starting at a `User`
/// message and running through the assistant turn(s) and tool results that
/// follow it.
fn segment_turns<'a>(messages: &'a [&'a ModelMessage]) -> Vec<Vec<&'a ModelMessage>> {
    let mut segments: Vec<Vec<&'a ModelMessage>> = Vec::new();
    let mut current: Vec<&'a ModelMessage> = Vec::new();
    for &message in messages {
        if matches!(message, ModelMessage::User(_)) && !current.is_empty() {
            segments.push(std::mem::take(&mut current));
        }
        current.push(message);
    }
    if !current.is_empty() {
        segments.push(current);
    }
    segments
}

/// Rebuilds the message list keeping only the last `keep` segments in full and
/// dropping the rest (the system message is preserved at the front).
fn keep_segments(
    messages: &[ModelMessage],
    segments: &[Vec<&ModelMessage>],
    keep: usize,
) -> Vec<ModelMessage> {
    let drop = segments.len().saturating_sub(keep);
    let mut kept: Vec<ModelMessage> = Vec::new();
    for (index, segment) in segments.iter().enumerate() {
        if index >= drop {
            kept.extend(segment.iter().map(|&message| message.clone()));
        }
    }
    match messages
        .iter()
        .find(|m| matches!(m, ModelMessage::System(_)))
    {
        Some(sys) => {
            let mut with_sys = Vec::with_capacity(kept.len() + 1);
            with_sys.push(sys.clone());
            with_sys.extend(kept);
            with_sys
        }
        None => kept,
    }
}

/// Builds a single-line summary for one completed turn segment.
fn turn_summary(segment: &[&ModelMessage]) -> String {
    let mut line = String::new();
    for message in segment {
        match message {
            ModelMessage::User(text) => {
                line.push_str("asked:");
                line.push_str(&truncate(text, 160));
            }
            ModelMessage::Assistant { text, tool_intents } => {
                if line.trim().is_empty() && text.trim().is_empty() {
                    // Nothing yet.
                } else if line.trim().is_empty() {
                    line.push_str(&truncate(text, 120));
                } else {
                    line.push_str(&truncate(text, 80));
                }
                for intent in tool_intents {
                    line.push_str(&format!(" ran {}(=)", intent.name));
                    if let Ok(json) = serde_json::to_string(&intent.arguments) {
                        line.push_str(&truncate(&json, 100));
                    }
                }
            }
            ModelMessage::ToolResult { content, .. } => {
                let preview = truncate(content, 120);
                if preview.is_empty() {
                    line.push_str(" ->");
                } else {
                    line.push_str(&format!(" -> {}", preview));
                }
            }
            _ => {}
        }
    }
    if line.trim().is_empty() {
        String::new()
    } else {
        format!("- {}", line.trim())
    }
}

/// Truncates `text` to at most `max` characters, appending an ellipsis when
/// trimmed so a summary line never grows unbounded.
fn truncate(text: &str, max: usize) -> String {
    let chars: String = text.chars().take(max).collect();
    if chars.chars().count() == text.chars().count() {
        chars
    } else if max == 0 {
        String::new()
    } else {
        format!("...{}", chars)
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use agent_runtime::ToolIntent;
    use serde_json::json;

    fn assistant(text: &str) -> ModelMessage {
        ModelMessage::Assistant {
            text: text.to_owned(),
            tool_intents: vec![ToolIntent {
                id: "c1".to_owned(),
                provider_id: None,
                name: "shell".to_owned(),
                arguments: json!({"command": "echo hi"}),
            }],
        }
    }

    fn result(name: &str, content: &str) -> ModelMessage {
        ModelMessage::ToolResult {
            call_id: "c1".to_owned(),
            name: name.to_owned(),
            content: content.to_owned(),
        }
    }

    fn user(text: &str) -> ModelMessage {
        ModelMessage::User(text.to_owned())
    }

    #[test]
    fn tokens_follow_the_four_chars_per_token_rule() {
        assert_eq!(estimate_tokens("abcd"), 1);
        assert_eq!(estimate_tokens("abcdefgh"), 2);
        assert_eq!(estimate_tokens(""), 0);
    }

    #[test]
    fn estimate_accounts_for_messages_and_tool_defs() {
        let msgs = vec![user("hello"), assistant("sure")];
        let total = estimate_messages(&msgs, 4);
        assert!(total > 0);
        assert!(estimate_messages(&msgs, 8) > total);
    }

    #[test]
    fn warmup_is_seventy_five_percent_of_limit() {
        let manager = ContextManager::new(1000, 3);
        assert_eq!(manager.warmup(), 750);
        assert!(!manager.should_compact(700));
        assert!(manager.should_compact(800));
    }

    #[test]
    fn progress_is_zero_below_warmup_and_one_at_limit() {
        let manager = ContextManager::with_bounds(1000, 750, 2);
        assert_eq!(manager.compaction_progress(500), 0.0);
        assert_eq!(manager.compaction_progress(750), 0.0);
        assert_eq!(manager.compaction_progress(1_000), 1.0);
        assert!((manager.compaction_progress(875) - 0.5).abs() < 0.01);
    }

    #[test]
    fn nothing_compacts_when_turns_are_few() {
        let mut manager = ContextManager::with_bounds(1000, 200, 3);
        let msgs = vec![
            ModelMessage::System("sys".to_owned()),
            user("a"),
            assistant("b"),
            result("shell", "ok"),
        ];
        let (condensed, compaction) = manager.compact(&msgs, 4);
        assert_eq!(compaction.compacted_turns, 0);
        assert_eq!(condensed.len(), msgs.len());
    }

    #[test]
    fn oldest_turns_roll_into_summary_young_keep_full() {
        let mut manager = ContextManager::with_bounds(10_000, 100, 1);
        let msgs = vec![
            ModelMessage::System("sys".to_owned()),
            user("first task"),
            assistant("doing first"),
            result("shell", "first output"),
            user("second task"),
            assistant("doing second"),
            result("shell", "second output"),
        ];
        let (condensed, compaction) = manager.compact(&msgs, 4);
        assert_eq!(compaction.compacted_turns, 1);
        assert!(manager.summary().contains("first task"));
        assert!(manager.summary().contains("first output"));
        assert!(matches!(condensed[0], ModelMessage::System(_)));
        let joined = condensed
            .iter()
            .map(|m| format!("{m:?}"))
            .collect::<String>();
        assert!(joined.contains("second task"));
        assert!(joined.contains("second output"));
        assert!(condensed.iter().any(|m| matches!(
            m,
            ModelMessage::User(text) if text.contains("Summary of prior work")
        )));
    }

    #[test]
    fn summary_is_bounded() {
        let mut manager = ContextManager::with_bounds(10_000, 100, 1);
        let mut msgs = vec![ModelMessage::System("sys".to_owned())];
        for i in 0..50 {
            let task = format!("task {i}");
            let work = format!("work {i}");
            let result_text = format!("result {i}");
            msgs.push(user(&task));
            msgs.push(assistant(&work));
            msgs.push(result("shell", &result_text));
        }
        let (condensed, _) = manager.compact(&msgs, 4);
        assert!(manager.summary.chars().count() <= MAX_SUMMARY_CHARS + 1);
        assert!(condensed.len() < msgs.len());
    }

    #[test]
    fn compaction_keeps_recent_turns_and_fits_under_the_window() {
        let mut manager = ContextManager::with_bounds(10_000, 100, 3);
        let mut msgs = vec![ModelMessage::System("sys".to_owned())];
        for i in 0..6 {
            msgs.push(user(&format!("task {i}")));
            msgs.push(assistant(&format!("work {i}")));
            msgs.push(result("shell", &format!("result {i}")));
        }
        let (condensed, compaction) = manager.compact(&msgs, 4);
        // More than the kept turns were rolled into the summary, but never more
        // than the configured number of recent turns were forced out of full
        // context: it keeps as many recent turns in full as fit.
        assert!(compaction.compacted_turns > 0);
        assert!(compaction.compacted_turns <= manager.keep_full_turns());
        let joined = condensed
            .iter()
            .map(|m| format!("{m:?}"))
            .collect::<String>();
        assert!(joined.contains("task 5"));
        assert!(manager.summary().contains("task 0"));
        assert!(estimate_messages(&condensed, 4) < manager.limit_tokens());
    }

    #[test]
    fn compaction_summary_contains_each_rolled_turn_exactly_once() {
        // Regression: when the window forces more than one pass of `keep` shrinking,
        // each pass must add only the newly compacted segment; older turn lines must
        // not be duplicated in the rolling summary.
        let mut manager = ContextManager::with_bounds(120, 90, 3);
        let mut msgs = vec![ModelMessage::System("system".to_owned())];
        for i in 0..6 {
            let text = "w".repeat(120);
            msgs.push(user(&format!("ask {i}")));
            msgs.push(assistant(&text));
            msgs.push(result("shell", "o".repeat(40).as_str()));
        }
        let (_, compaction) = manager.compact(&msgs, 4);
        assert!(compaction.compacted_turns >= 2, "force at least two passes");
        let summary = manager.summary().to_owned();
        for i in 0..compaction.compacted_turns {
            let needle = format!("ask {i}");
            let count = summary.matches(&needle).count();
            assert_eq!(
                count, 1,
                "summary line for turn {i} appears {count} times\nsummary:\n{summary}"
            );
        }
    }

    #[test]
    fn compaction_reduces_full_turns_when_the_window_is_tight() {
        // When keeping the configured recent turns would overflow the window,
        // compaction rolls more into the summary, always keeping the single most
        // recent turn in full as the floor.
        let mut manager = ContextManager::with_bounds(120, 90, 3);
        let mut msgs = vec![ModelMessage::System("system".to_owned())];
        for i in 0..6 {
            let text = "w".repeat(120);
            msgs.push(user(&format!("ask {i}")));
            msgs.push(assistant(&text));
            msgs.push(result("shell", "o".repeat(40).as_str()));
        }
        let (_, compaction) = manager.compact(&msgs, 4);
        // keep in [1, keep_full_turns], so compacted turns in
        // [total - keep_full_turns, total - 1].
        assert!(compaction.compacted_turns >= 6 - manager.keep_full_turns());
        assert!(compaction.compacted_turns <= 5);
    }
}

//! The worker thread that runs a session loop off the UI thread.
//!
//! The model transport and sandbox executor are blocking, so the loop runs on a
//! detached thread and pushes [`Event`]s over a bounded channel. The UI owns the
//! channel receiver and renders each event. Cancellation flows from a shared
//! [`CancellationToken`], and new prompts flow from the UI over a prompt channel.

use std::sync::mpsc;
use std::thread::{self, JoinHandle};

use agent_runtime::{CancellationToken, ModelTransport};

use crate::context::ContextManager;
use crate::error::{Error, Result};
use crate::session::{AgentRunner, AgentSession, Event, EventSink, Recorder, ToolExecutor};

/// Receives [`Event`]s from the worker; implements [`EventSink`].
struct ChannelSink(mpsc::SyncSender<Event>);

impl EventSink for ChannelSink {
    fn send(&self, event: Event) -> Result<()> {
        self.0.send(event).map_err(|_| Error::ChannelClosed)
    }
}

/// A handle to a running session, holding the cancellation token and thread.
pub struct SessionHandle {
    cancellation: CancellationToken,
    thread: Option<JoinHandle<()>>,
}

impl SessionHandle {
    /// Requests cancellation of the running turn.
    pub fn cancel(&self) {
        self.cancellation.cancel();
    }

    /// Reports whether a turn is still running.
    #[allow(dead_code)]
    pub fn is_running(&self) -> bool {
        self.thread.is_some()
    }
}

impl Drop for SessionHandle {
    fn drop(&mut self) {
        self.cancel();
        if let Some(thread) = self.thread.take() {
            let _ = thread.join();
        }
    }
}

/// Starts a session loop on a worker thread and returns a handle, the event
/// receiver owned by the UI, and the prompt sender the UI uses to submit prompts.
///
/// `context` bounds the model's context across the whole session, and an
/// optional `recorder` captures the durable record (journal + transcript,
/// including reasoning) for later inspection.
pub fn start<M, E>(
    mut session: AgentSession,
    transport: M,
    executor: E,
    mut context: ContextManager,
    mut recorder: Option<Box<dyn Recorder>>,
) -> (SessionHandle, mpsc::Receiver<Event>, mpsc::Sender<String>)
where
    M: ModelTransport + Send + 'static,
    E: ToolExecutor + Send + 'static,
{
    let (prompt_tx, prompt_rx) = mpsc::channel::<String>();
    let (tx, rx) = mpsc::sync_channel(128);
    let cancellation = CancellationToken::new();
    let handle_cancellation = cancellation.clone();
    let thread = thread::spawn(move || {
        let sink = ChannelSink(tx);
        // The worker stays alive across turns; it exits only when every prompt
        // sender is dropped. `AgentRunner::run` records each turn's session
        // boundary in the durable recorder, so the worker does not manage the
        // record lifecycle itself. Cancellation re-arms the token after each
        // turn so a cancelled turn does not end the session.
        while let Some(text) = wait_for_prompt(&prompt_rx) {
            session.push_user(text);
            let runner = AgentRunner::default();
            // Borrow the recorder only for this run; the borrow ends before the
            // next iteration, and each run starts and finishes its own record.
            let _ = runner
                .run(
                    &mut session,
                    &transport,
                    &executor,
                    &sink,
                    &cancellation,
                    &mut context,
                    borrow_recorder(&mut recorder),
                )
                .unwrap_or_else(|_| crate::session::RunSummary::default());
            cancellation.reset();
        }
    });
    (
        SessionHandle {
            cancellation: handle_cancellation,
            thread: Some(thread),
        },
        rx,
        prompt_tx,
    )
}

/// Blocks until the next prompt arrives or every prompt sender is dropped.
/// Returns `None` when the channel closes, which ends the worker.
fn wait_for_prompt(rx: &mpsc::Receiver<String>) -> Option<String> {
    rx.recv().ok()
}

/// Reborrow the recorder as `Option<&mut dyn Recorder>` for a single call.
///
/// The split borrow reborrows through the `Box`, so the mutable borrow ends
/// with the call instead of being extended across the recorder's lifetime (as a
/// direct `recorder.as_deref_mut()` borrow would be, because the value owns its
/// drop). The recorder is reused across turns, so each call needs a fresh one.
fn borrow_recorder(recorder: &mut Option<Box<dyn Recorder>>) -> Option<&mut dyn Recorder> {
    match recorder {
        Some(boxed) => Some(&mut **boxed),
        None => None,
    }
}

/// Builds the default system prompt for the agent, describing its sandbox scope.
pub fn system_prompt(write_root: &str) -> String {
    format!(
        "You are a coding agent running inside a sandbox. The working directory is mounted at {write_root} \
         and is the only place you may write. You can read files under {write_root} and the read-only system \
         layout. Prefer small, reversible steps. When editing files, write complete files. State what you did."
    )
}

//! The transport-agnostic agent session and multi-turn loop.
//!
//! [`AgentSession`] owns the ordered conversation and builds turns.
//! [`AgentRunner::run`] drives the loop against any [`ModelTransport`], executes
//! the tool intents via a [`ToolExecutor`], and forwards progress through an
//! [`EventSink`]. Nothing here performs blocking subprocess I/O directly; the
//! executor is injected so the loop is unit-testable with fakes.

use std::time::Instant;

use agent_runtime::{
    CancellationToken, ModelMessage, ModelRequest, ModelStreamEvent, ModelTransport, ModelTurn,
    ModelUsage, ReasoningEffort, ToolChoice, ToolDefinition, ToolIntent,
};

use crate::config::Model;
use crate::context::ContextManager;
use crate::error::Result;
use crate::sandbox::ToolOutcome;

/// The maximum number of model turns in one session before the loop stops.
pub const MAX_TURNS: u32 = 50;
/// The maximum bytes of a tool result folded back to the model.
pub const MAX_TOOL_RESULT_BYTES: usize = 64 * 1024;

/// A progress event emitted while a session runs.
#[derive(Debug, Clone)]
pub enum Event {
    /// A model turn began.
    TurnStart { model: String },
    /// A fragment of model reasoning text.
    Reasoning(String),
    /// A fragment of model answer text.
    Text(String),
    /// A tool call was proposed by the model.
    ToolCall { name: String },
    /// A tool call finished; `failed` marks a non-zero or non-exiting result.
    ToolResult { name: String, failed: bool },
    /// The session produced a final answer.
    Finished { message: String },
    /// The session failed before producing an answer.
    Failed(String),
    /// A non-terminal notice (for example, a compaction that trimmed the model
    /// context). Rendered as a muted line rather than an error.
    Note(String),
    /// Periodic context/token accounting, emitted after each turn, feeding the
    /// live speed stat, the context bargraph, and the compaction progress bar.
    Progress {
        /// Cumulative input tokens so far.
        input_tokens: u64,
        /// Cumulative output tokens so far.
        output_tokens: u64,
        /// Tokens the model currently holds in context.
        context_tokens: usize,
        /// The model context limit, in tokens.
        context_limit: usize,
        /// Context utilization against the limit (`0.0..=1.0+`).
        context_utilization: f64,
        /// How close compaction is to the hard limit (`0.0..=1.0`).
        compaction_progress: f64,
        /// Session-wide tokens per second.
        tokens_per_sec: f64,
        /// Cumulative provider tokens observed across the session.
        total_tokens: u64,
        /// Wall-clock seconds since the run started.
        elapsed_secs: f64,
    },
}

/// The sink that receives [`Event`]s, typically a channel to the UI.
pub trait EventSink: Send {
    /// Forwards one event; an error (e.g. a closed channel) stops the loop.
    fn send(&self, event: Event) -> Result<()>;
}

/// The transport-agnostic conversation state.
pub struct AgentSession {
    model: Model,
    thinking_effort: ReasoningEffort,
    system_prompt: String,
    messages: Vec<ModelMessage>,
    tool_defs: Vec<ToolDefinition>,
    answer: Option<String>,
}

impl AgentSession {
    /// Creates an empty session for one model.
    pub fn new(
        model: Model,
        thinking_effort: ReasoningEffort,
        tool_defs: Vec<ToolDefinition>,
        system_prompt: String,
    ) -> Self {
        AgentSession {
            model,
            thinking_effort,
            system_prompt,
            messages: Vec::new(),
            tool_defs,
            answer: None,
        }
    }

    /// Appends a user message. The session then has pending work.
    pub fn push_user(&mut self, text: impl Into<String>) {
        self.messages.push(ModelMessage::User(text.into()));
    }

    /// The model selector id for this session.
    pub fn model_selector(&self) -> &str {
        &self.model.id
    }

    /// The tool definitions offered to the model, whose count is used to size
    /// the model context. Exposed so context accounting can include them.
    pub fn tool_definitions(&self) -> &[ToolDefinition] {
        &self.tool_defs
    }

    /// The next turn request, or `None` when there is no pending work.
    pub fn next_request(&self) -> Option<ModelRequest> {
        if self.messages.is_empty() {
            return None;
        }
        // The system prompt is host-owned instructions, so it leads the
        // conversation as a `System` message ahead of the user history.
        let mut messages = Vec::with_capacity(self.messages.len() + 1);
        if !self.system_prompt.is_empty() {
            messages.push(ModelMessage::System(self.system_prompt.clone()));
        }
        messages.extend(self.messages.iter().cloned());
        Some(ModelRequest {
            model: self.model.model.clone(),
            messages,
            tools: self.tool_defs.clone(),
            tool_choice: ToolChoice::Auto,
            reasoning_effort: Some(self.thinking_effort),
            output_schema: None,
        })
    }

    /// Folds an assistant turn into the conversation and returns the tool
    /// intents it proposed, which the caller must execute.
    pub fn apply_assistant(&mut self, turn: ModelTurn) -> Vec<ToolIntent> {
        let tool_intents = turn.tool_intents.clone();
        self.messages.push(ModelMessage::Assistant {
            text: turn.text.clone(),
            tool_intents: turn.tool_intents,
        });
        if tool_intents.is_empty() {
            self.answer = Some(turn.text);
        }
        tool_intents
    }

    /// Records one tool result, redacted and bounded, as a model message.
    pub fn record_tool_result(&mut self, call_id: &str, name: &str, outcome: &ToolOutcome) {
        let mut body = outcome.output_text(MAX_TOOL_RESULT_BYTES);
        let stderr = outcome.error_text(MAX_TOOL_RESULT_BYTES);
        if !stderr.is_empty() {
            if !body.is_empty() {
                body.push('\n');
            }
            body.push_str(&format!("[stderr] {stderr}"));
        }
        if outcome.timed_out {
            body.push_str("\n[sandbox: wall-clock timeout]");
        }
        if outcome.output_limit_exceeded {
            body.push_str(&format!(
                "\n[sandbox: output limited to {} bytes]",
                MAX_TOOL_RESULT_BYTES
            ));
        }
        self.messages.push(ModelMessage::ToolResult {
            call_id: call_id.to_owned(),
            name: name.to_owned(),
            content: body,
        });
    }

    /// The token size of the conversation that would next be sent to the model,
    /// plus the always-present tool definitions. Used to track context usage.
    pub fn estimate_context_tokens(&self, tool_definitions: usize) -> usize {
        crate::context::estimate_messages(&self.messages, tool_definitions)
    }

    /// Compacts the conversation when it crosses the manager's warm-up threshold,
    /// rolling the oldest completed turns into a summary. Returns the compaction
    /// metadata when anything was compacted, so the caller can log and display it.
    pub fn maybe_compact(
        &mut self,
        manager: &mut ContextManager,
        tool_definitions: usize,
    ) -> Option<crate::context::Compaction> {
        let context_tokens = self.estimate_context_tokens(tool_definitions);
        if !manager.should_compact(context_tokens) {
            return None;
        }
        let (condensed, compaction) = manager.compact(&self.messages, tool_definitions);
        self.messages = condensed;
        Some(compaction)
    }

    /// The current context utilization fraction against the hard limit.
    pub fn utilization(&self, manager: &ContextManager, tool_definitions: usize) -> f64 {
        let context_tokens = self.estimate_context_tokens(tool_definitions);
        manager.utilization(context_tokens)
    }

    /// How close compaction is to the hard limit, as a progress fraction.
    pub fn compaction_progress(&self, manager: &ContextManager, tool_definitions: usize) -> f64 {
        let context_tokens = self.estimate_context_tokens(tool_definitions);
        manager.compaction_progress(context_tokens)
    }
}

/// Executes a tool intent and returns its sandbox outcome. Injected into the
/// loop so the loop itself needs no process or filesystem access. The executor
/// owns the working directory and the sandbox configuration.
pub trait ToolExecutor: Send {
    /// Renders and executes one tool intent inside the sandbox.
    fn execute(&self, intent: &ToolIntent, cancellation: &CancellationToken)
    -> Result<ToolOutcome>;
}

/// A durable, pluggable sink for the session record. The production
/// implementation ([`crate::session_log::SessionLog`]) writes a structured
/// journal and a readable transcript; tests can record in memory. Recording the
/// full reasoning trace here is what keeps thinking inspectable even after
/// compaction removes it from the model context.
pub trait Recorder: Send {
    /// Writes the session-start event. Called once, before the first turn.
    fn session_start(&mut self);
    /// Begins one turn, capturing its reasoning trace. Returns the turn index
    /// used by later tool records.
    fn turn_start(&mut self, turn: &ModelTurn) -> usize;
    /// Completes one turn, folding in provider token usage.
    fn turn_finish(&mut self, turn: usize, usage: &Option<ModelUsage>, finish_reason: &str);
    /// Records an approved tool call and its sandbox outcome.
    fn tool_result(
        &mut self,
        turn: usize,
        call_id: &str,
        tool: &str,
        args: &serde_json::Value,
        outcome: &ToolOutcome,
    );
    /// Writes the terminal session-finish event with session totals.
    fn session_finish(&mut self, success: bool);
}

/// The outcome of running a session loop.
#[derive(Debug, Clone, PartialEq, Eq, Default)]
pub struct RunSummary {
    /// The final answer text, when the loop produced one.
    pub answer: Option<String>,
    /// The number of model turns performed.
    pub turns: u32,
    /// The number of tool calls executed.
    pub tools_executed: u32,
    /// Whether the user cancelled the loop.
    pub cancelled: bool,
    /// Whether the loop stopped after too many turns.
    pub exhausted: bool,
}

/// Maps a `FinishReason` to a short, stable string for the session record.
fn finish_reason_str(reason: &agent_runtime::FinishReason) -> &str {
    match reason {
        agent_runtime::FinishReason::Stop => "stop",
        agent_runtime::FinishReason::Length => "length",
        agent_runtime::FinishReason::ToolCalls => "tool_calls",
        agent_runtime::FinishReason::ContentFilter => "content_filter",
        agent_runtime::FinishReason::Other(s) => s.as_str(),
    }
}

/// The multi-turn loop driver.
pub struct AgentRunner {
    pub max_turns: u32,
}

impl Default for AgentRunner {
    fn default() -> Self {
        AgentRunner {
            max_turns: MAX_TURNS,
        }
    }
}

impl AgentRunner {
    /// Runs the loop to completion, streaming [`Event`]s through `sink`.
    ///
    /// Each parameter is a distinct collaborator the loop needs: `session` (the
    /// conversation), `transport` (the model), `executor` (sandbox tools),
    /// `sink` (events to the UI), `cancellation` (cooperative interrupt),
    /// `context` (rolling compaction bound), and an optional `recorder` that
    /// captures the durable record (reasoning included) for later inspection.
    /// Compaction only ever trims the model context; the recorder is the
    /// durable source of truth.
    #[allow(clippy::too_many_arguments)]
    pub fn run<M, E, S>(
        &self,
        session: &mut AgentSession,
        transport: &M,
        executor: &E,
        sink: &S,
        cancellation: &CancellationToken,
        context: &mut ContextManager,
        mut recorder: Option<&mut dyn Recorder>,
    ) -> Result<RunSummary>
    where
        M: ModelTransport,
        E: ToolExecutor,
        S: EventSink,
    {
        let tool_definitions = session.tool_definitions().len();
        let mut summary = RunSummary::default();
        let mut turn = 0u32;
        let started_at = Instant::now();
        let mut cumulative_tokens: u64 = 0;
        let mut cumulative_input: u64 = 0;
        let mut cumulative_output: u64 = 0;

        // Record the durable session boundary before any turn, so the record
        // has a clean start (and a matching finish) even for an empty run.
        if let Some(recorder) = recorder.as_mut() {
            recorder.session_start();
        }

        while turn < self.max_turns {
            let Some(request) = session.next_request() else {
                break;
            };
            turn += 1;

            sink.send(Event::TurnStart {
                model: session.model_selector().to_owned(),
            })?;

            // Stream the turn, forwarding text/reasoning to the UI and recording
            // each tool intent the model proposes so the UI can show it live.
            // The callback must return `agent_runtime::Result`, so forwarding to
            // the sink is best-effort: a closed channel only means the UI is gone,
            // which the loop surfaces on the next turn's own `sink.send`.
            let result = transport.stream(&request, cancellation, &mut |event| match event {
                ModelStreamEvent::TextDelta(delta) => {
                    if !delta.is_empty() {
                        let _ = sink.send(Event::Text(delta));
                    }
                    Ok(())
                }
                ModelStreamEvent::ReasoningDelta(delta) => {
                    if !delta.is_empty() {
                        let _ = sink.send(Event::Reasoning(delta));
                    }
                    Ok(())
                }
                ModelStreamEvent::ToolIntent(intent) => {
                    let _ = sink.send(Event::ToolCall {
                        name: intent.name.clone(),
                    });
                    Ok(())
                }
            });

            let turn_value = match result {
                Ok(turn) => turn,
                Err(error) => {
                    sink.send(Event::Failed(error.to_string()))?;
                    summary.cancelled = cancellation.is_cancelled();
                    return Ok(summary);
                }
            };

            // Capture the full record first: reasoning + finish + usage. This is
            // the durable copy that compaction and the UI may later drop.
            let turn_index = recorder.as_mut().map(|rec| rec.turn_start(&turn_value));
            let finish_reason = finish_reason_str(&turn_value.finish_reason);
            if let Some(recorder) = recorder.as_mut() {
                recorder.turn_finish(turn_index.unwrap_or(0), &turn_value.usage, finish_reason);
            }
            if let Some(usage) = &turn_value.usage {
                cumulative_tokens += usage.total_tokens;
                cumulative_input += usage.input_tokens;
                cumulative_output += usage.output_tokens;
            }

            // No tools proposed: this assistant text is the final answer.
            let tool_intents = session.apply_assistant(turn_value);
            let terminal = tool_intents.is_empty();

            if !terminal {
                for intent in tool_intents {
                    if cancellation.is_cancelled() {
                        summary.cancelled = true;
                        return Ok(summary);
                    }
                    match executor.execute(&intent, cancellation) {
                        Ok(outcome) => {
                            summary.tools_executed += 1;
                            session.record_tool_result(&intent.id, &intent.name, &outcome);
                            if let Some(recorder) = recorder.as_mut() {
                                recorder.tool_result(
                                    turn_index.unwrap_or(0),
                                    &intent.id,
                                    &intent.name,
                                    &intent.arguments,
                                    &outcome,
                                );
                            }
                            let _ = sink.send(Event::ToolResult {
                                name: intent.name.clone(),
                                failed: outcome.failed(),
                            });
                        }
                        Err(error) => {
                            // A rejected or failed tool is reported, not fatal.
                            if let Some(recorder) = recorder.as_mut() {
                                recorder.tool_result(
                                    turn_index.unwrap_or(0),
                                    &intent.id,
                                    &intent.name,
                                    &intent.arguments,
                                    &crate::sandbox::ToolOutcome::rejected(),
                                );
                            }
                            let _ = sink.send(Event::ToolResult {
                                name: intent.name.clone(),
                                failed: true,
                            });
                            let _ = sink.send(Event::Failed(error.describe()));
                        }
                    }

                    // Compact the model context now that this turn is fully
                    // recorded, so the next request stays within the model's
                    // window. The record is untouched.
                    if let Some(compaction) = session.maybe_compact(context, tool_definitions)
                        && compaction.compacted_turns > 0
                    {
                        let _ = sink.send(Event::Note(format!(
                        "context compacted: {} earlier turn(s) rolled into a summary (kept in the session log)",
                        compaction.compacted_turns
                    )));
                    }
                }
            }

            // Report accounting after every turn — including the final one,
            // whose report doubles as the session's last — so the live stats
            // bar (speed, context utilization, compaction progress, and the
            // compaction ETA) tracks the session while it runs, not only when
            // it ends.
            self.emit_progress(
                sink,
                session,
                context,
                cumulative_input,
                cumulative_output,
                cumulative_tokens,
                started_at,
            )?;
            if terminal {
                break;
            }
        }

        if turn >= self.max_turns {
            summary.exhausted = true;
        }
        summary.turns = turn;
        summary.answer = session.answer.clone();
        if let Some(answer) = &summary.answer {
            let _ = sink.send(Event::Finished {
                message: answer.clone(),
            });
        }
        // Close the durable session record. A run that was cancelled or
        // exhausted after too many turns is recorded as unsuccessful; a normal
        // completion (with or without a final answer) is recorded as success.
        let success = !summary.cancelled && !summary.exhausted;
        if let Some(recorder) = recorder.as_mut() {
            recorder.session_finish(success);
        }
        Ok(summary)
    }

    /// Emits a single accounting event so the UI can update the speed stat, the
    /// context bargraph, and the compaction progress bar. Non-fatal: a dropped
    /// sink only means the UI is gone.
    #[allow(clippy::too_many_arguments)]
    fn emit_progress<S: EventSink>(
        &self,
        sink: &S,
        session: &AgentSession,
        context: &ContextManager,
        input_tokens: u64,
        output_tokens: u64,
        total_tokens: u64,
        started_at: Instant,
    ) -> Result<()> {
        let context_tokens = session.estimate_context_tokens(session.tool_definitions().len());
        let elapsed = started_at.elapsed().as_secs_f64().max(1e-9);
        let tokens_per_sec = total_tokens as f64 / elapsed;
        sink.send(Event::Progress {
            input_tokens,
            output_tokens,
            context_tokens,
            context_limit: context.limit_tokens(),
            context_utilization: session.utilization(context, session.tool_definitions().len()),
            compaction_progress: session
                .compaction_progress(context, session.tool_definitions().len()),
            tokens_per_sec,
            total_tokens,
            elapsed_secs: elapsed,
        })
    }
}

